CREATE DATABASE IF NOT EXISTS edumart_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE edumart_db;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','admin') NOT NULL DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS materials(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,subject VARCHAR(100) NOT NULL,price_paise INT UNSIGNED NOT NULL,file_url VARCHAR(1000),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coupons(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,discount_percent TINYINT UNSIGNED NOT NULL,expires_at DATETIME NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,CHECK(discount_percent BETWEEN 1 AND 90));
CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,material_id BIGINT UNSIGNED NOT NULL,coupon_id BIGINT UNSIGNED NULL,amount_paise INT UNSIGNED NOT NULL,status ENUM('created','paid','failed') NOT NULL DEFAULT 'created',razorpay_order_id VARCHAR(100) NOT NULL UNIQUE,razorpay_payment_id VARCHAR(100) NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(material_id) REFERENCES materials(id),FOREIGN KEY(coupon_id) REFERENCES coupons(id));
INSERT INTO materials(title,description,subject,price_paise) SELECT 'Class 10 Mathematics Notes','Chapter-wise revision notes.','Mathematics',9900 WHERE NOT EXISTS(SELECT 1 FROM materials WHERE title='Class 10 Mathematics Notes');
INSERT INTO materials(title,description,subject,price_paise) SELECT 'Physics Formula Handbook','Quick formula reference.','Physics',14900 WHERE NOT EXISTS(SELECT 1 FROM materials WHERE title='Physics Formula Handbook');
